/* @lc app=leetcode id=3348 lang=kotlin */ class Solution { fun fd(r: Long): List<Int>? = (9 downTo 2).fold(r to listOf<Int>()) { (x, l), d -> generateSequence(x to l) { (y, ll) -> if (y % d == 0L) y / d to ll + d else null }.last() }.let { (x, l) -> if (x == 1L) l.sorted() else null } fun ex(c: Int): IntArray = arrayOf(intArrayOf(0, 0, 0, 0), intArrayOf(0, 0, 0, 0), intArrayOf(1, 0, 0, 0), intArrayOf(0, 1, 0, 0), intArrayOf(2, 0, 0, 0), intArrayOf(0, 0, 1, 0), intArrayOf(1, 1, 0, 0), intArrayOf(0, 0, 0, 1), intArrayOf(3, 0, 0, 0), intArrayOf(0, 2, 0, 0))[c] fun sb(e: IntArray, f: IntArray): IntArray = IntArray(4) { e[it] - minOf(e[it], f[it]) } fun vl(e: IntArray): Long = (0 until 4).fold(1L) { a, k -> (1..e[k]).fold(a) { x, _ -> x * longArrayOf(2, 3, 5, 7)[k] } } fun cn(e: IntArray): Int = (e[1] / 2).let { a9 -> (e[0] / 3).let { a8 -> minOf(e[1] - 2 * a9, e[0] - 3 * a8).let { a6 -> (e[0] - 3 * a8 - a6).let { r2 -> a9 + a8 + e[3] + a6 + e[2] + r2 / 2 + r2 % 2 + (e[1] - 2 * a9 - a6) } } } } fun fe(t: Long): IntArray = longArrayOf(2, 3, 5, 7).map { p -> generateSequence(t) { if (it % p == 0L) it / p else null }.count() - 1 }.toIntArray() fun smallestNumber(num: String, t: Long): String = fe(t).let { e0 -> if (vl(e0) != t) "-1" else num.length.let { n -> num.indexOf('0').let { if (it < 0) n - 1 else it }.let { z -> num.take(z).runningFold(e0) { a, c -> sb(a, ex(c - '0')) }.let { E -> if ('0' !in num && num.fold(e0) { a, c -> sb(a, ex(c - '0')) }.all { it == 0 }) num else (z downTo 0).firstNotNullOfOrNull { i -> ((num[i] - '0' + 1)..9).firstNotNullOfOrNull { d -> sb(E[i], ex(d)).let { r -> if (cn(r) <= n - i - 1) fd(vl(r))!!.let { l -> num.take(i) + d + "1".repeat(n - i - 1 - l.size) + l.joinToString("") } else null } } } ?: fd(t)!!.let { l -> "1".repeat(maxOf(0, n + 1 - l.size)) + l.joinToString("") } } } } } }